pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set MinSum to 1 wei so small amounts are withdrawable (default is 1 ether)
        // MinSum is a public state variable, but we must set it via constructor? No, constructor doesn't set it.
        // Actually the constructor is address(log) only. So we need to set it via c.setMinSum? There's no setter.
        // Wait, the contract has public MinSum = 1 ether, no setter. So to make Collect work we must deposit >=1 ether.
        // But the bug triggers on deposit (subtraction) making balance negative on Collect.
        // So we use 1 ether deposit and then try to Collect 1 ether.
        vm.deal(address(this), 2 ether);
        // Call Put with 1 ether, unlockTime = block.timestamp so Collect is immediately allowed.
        c.Put{value: 1 ether}(block.timestamp);
        // Now acc.balance = 1 ether in reference (add) and 0 in buggy (sub).
        // Since MinSum = 1 ether, reference allows Collect(1 ether), buggy reverts because balance < _am (0 < 1).
        // Actually buggy balance is 0 so Collect would fail the condition acc.balance >= _am. So it doesn't revert internally, just doesn't execute the call.
        // But we need a difference in observable public state. Let's check Acc[address(this)].balance after Collect attempt.
        // Reference: after successful Collect, balance becomes 0.
        // Buggy: balance stays 0 (no change).
        // So we can assert Acc[address(this)].balance == 0 for both? No, reference is 0 after Collect, buggy was already 0. Same.
        // Need a different approach: try Collect with amount that reference can do and buggy cannot due to negative subtraction.
        // Actually if buggy subtracts 1 ether on deposit, balance becomes 0. Then if we deposit again, balance -= msg.value => goes negative (sub_uint256 reverts on underflow).
        // Let's try: first Put 1 ether -> buggy balance 0, reference balance 1 ether.
        // Then try Put again 1 ether -> buggy sub_uint256(0, 1) reverts, reference add_uint256(1,1)=2 ether.
        // So the second Put reverts in buggy. That's a observable difference: we can check whether second Put reverts.
        vm.deal(address(this), 2 ether);
        c.Put{value: 1 ether}(block.timestamp); // first deposit
        // Now attempt second deposit
        bool ok;
        try c.Put{value: 1 ether}(block.timestamp) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: ok == true (no revert)
        // Buggy: ok == false (revert due to underflow in sub_uint256)
        assertTrue(ok == true, "Second Put should succeed in reference but fails in buggy");
    }
}

