pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // User A puts 1 ether with unlockTime = block.timestamp
        vm.deal(address(0xA), 1 ether);
        vm.prank(address(0xA));
        c.Put{value: 1 ether}(block.timestamp);
        // Warp past unlockTime to allow Collect
        vm.warp(block.timestamp + 1);
        // User A collects 1 ether – should succeed
        vm.prank(address(0xA));
        c.Collect(1 ether);
        // User B puts 0 ether (just resets unlockTime to now)
        vm.deal(address(0xB), 0 ether);
        vm.prank(address(0xB));
        c.Put{value: 0}(block.timestamp);
        // Warp again so unlockTime passes
        vm.warp(block.timestamp + 1);
        // User B tries to collect 1 ether – in reference it reverts (balance < MinSum)
        vm.prank(address(0xB));
        bool ok;
        try c.Collect(1 ether) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference (correct) reverts → ok = false; mutant (bug) does not → ok = true
        // Wait, but the description says test must pass on reference and fail on bug
        // So we assertFalse(ok) : reference passes (revert) and mutant fails (no revert)
        assertFalse(ok);
    }
}

