        // Setup: warp to a known timestamp
        vm.warp(1000);

        // User A puts 2 ether with unlockTime = now (so it passes)
        address userA = address(0x1);
        vm.deal(userA, 2 ether);
        vm.prank(userA);
        c.Put{value: 2 ether}(1000);

        // User B puts 0 ether with unlockTime = now
        address userB = address(0x2);
        vm.deal(userB, 1 ether);
        vm.prank(userB);
        c.Put{value: 0 ether}(1000);

        // Warp past unlockTime
