        // User B tries to Collect 0.5 ether
        vm.prank(userB);
        bool ok;
        try c.Collect(0.5 ether) { ok = true; } catch { ok = false; }

        // Reference reverts (balance=0 < MinSum=1 ether), mutant succeeds
        assertTrue(!ok);
    }
}

